CREATE POLICY himmah_brand_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='himmah-branding' AND public.himmah_admin());
CREATE POLICY himmah_brand_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='himmah-branding' AND public.is_staff(auth.uid()));
CREATE FUNCTION public.himmah_guard_attempt() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.approved_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'النتيجة المعتمدة لا تستبدل'; END IF; RETURN NEW; END $$;
CREATE TRIGGER himmah_attempt_immutable BEFORE UPDATE ON public.himmah_attempts FOR EACH ROW EXECUTE FUNCTION public.himmah_guard_attempt();
CREATE FUNCTION public.himmah_correct(_attempt uuid,_mistakes integer,_warnings integer,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.himmah_attempts; p public.himmah_participants; b public.himmah_attempts; n integer; BEGIN IF NOT public.himmah_admin() THEN RAISE EXCEPTION 'التصحيح للإدارة فقط'; END IF; IF _mistakes NOT BETWEEN 0 AND 10000 OR _warnings NOT BETWEEN 0 AND 10000 OR _mistakes IS NULL OR _warnings IS NULL OR length(trim(coalesce(_reason,'')))<3 THEN RAISE EXCEPTION 'أدخل أعدادًا صحيحة وسبب التصحيح'; END IF; SELECT * INTO a FROM public.himmah_attempts WHERE id=_attempt AND approved_at IS NOT NULL; SELECT * INTO p FROM public.himmah_participants WHERE id=a.participant_id FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'النتيجة غير موجودة'; END IF; SELECT coalesce(max(attempt_no),0)+1 INTO n FROM public.himmah_attempts WHERE participant_id=p.id AND hizb=a.hizb; INSERT INTO public.himmah_attempts(participant_id,reviewer_id,hizb,attempt_no,request_id,started_at,ended_at,duration_seconds,mistakes,warnings,error_weight,fail_threshold,equivalent_errors,status,approved_at) VALUES(p.id,a.reviewer_id,a.hizb,n,gen_random_uuid(),a.started_at,a.ended_at,a.duration_seconds,_mistakes,_warnings,a.error_weight,a.fail_threshold,_mistakes*a.error_weight+_warnings,CASE WHEN _mistakes*a.error_weight+_warnings>=a.fail_threshold THEN 'fail' ELSE 'pass' END,clock_timestamp()) RETURNING * INTO b; INSERT INTO public.himmah_audit(day_id,attempt_id,actor_id,action,previous_value,new_value) VALUES(p.day_id,b.id,auth.uid(),'correction',to_jsonb(a),to_jsonb(b)||jsonb_build_object('reason',_reason)); RETURN to_jsonb(b); END $$;
REVOKE ALL ON FUNCTION public.himmah_correct(uuid,integer,integer,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_correct(uuid,integer,integer,text) TO authenticated;
CREATE FUNCTION public.himmah_guard_participant() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF cardinality(NEW.hizbs) IS NULL OR cardinality(NEW.hizbs)=0 OR EXISTS(SELECT 1 FROM unnest(NEW.hizbs) h WHERE h IS NULL OR h NOT BETWEEN 1 AND 60) THEN RAISE EXCEPTION 'أحزاب غير صحيحة'; END IF; RETURN NEW; END $$;
CREATE TRIGGER himmah_participant_validate BEFORE INSERT OR UPDATE ON public.himmah_participants FOR EACH ROW EXECUTE FUNCTION public.himmah_guard_participant();
CREATE OR REPLACE FUNCTION public.himmah_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active AND role='manager') $$;
CREATE OR REPLACE FUNCTION public.himmah_view_halaqa(_halaqa uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.active AND public.is_staff(p.id) AND (p.role IN ('manager','supervisor','assistant_supervisor','secretary','admin_staff') OR _halaqa=p.assigned_halaqa_id OR _halaqa=p.assigned_assistant_halaqa_id)) $$;
CREATE OR REPLACE FUNCTION public.himmah_register(_invite text,_name text,_phone text,_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.himmah_days; r uuid; BEGIN SELECT * INTO d FROM public.himmah_days WHERE invite_key=_invite AND registration_open AND expires_at>now() FOR UPDATE; IF d.id IS NULL THEN RAISE EXCEPTION 'الرابط غير متاح أو انتهت صلاحيته'; END IF; IF _name IS NULL OR _phone IS NULL OR _token IS NULL OR length(trim(_name)) NOT BETWEEN 3 AND 120 OR _phone !~ '^(05[0-9]{8}|9665[0-9]{8})$' OR _token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'الاسم أو الجوال غير صحيح'; END IF; IF EXISTS(SELECT 1 FROM public.himmah_reviewers WHERE day_id=d.id AND phone=_phone AND created_at>now()-interval '1 minute') OR (SELECT count(*) FROM public.himmah_reviewers WHERE day_id=d.id)>2000 THEN RAISE EXCEPTION 'يرجى الانتظار قبل إعادة التسجيل'; END IF; INSERT INTO public.himmah_reviewers(day_id,full_name,phone,token_hash) VALUES(d.id,trim(_name),_phone,encode(extensions.digest(_token,'sha256'),'hex')) RETURNING id INTO r; RETURN jsonb_build_object('day_id',d.id,'reviewer_id',r); END $$;
